param([string]$PackageRoot="art-production/test-room-v01")
$ErrorActionPreference="Stop";Add-Type -AssemblyName System.Drawing
$jobs=@(@{Name="dust_a";W=512;H=512},@{Name="fog_a";W=1024;H=256},@{Name="rays_a";W=512;H=512},@{Name="fallout_a";W=512;H=512})
foreach($j in $jobs){$src=[Drawing.Bitmap]::new((Resolve-Path (Join-Path $PackageRoot "source/vfx/tr01_vfx_$($j.Name)_source.png")).Path);$dst=[Drawing.Bitmap]::new($j.W,$j.H,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($dst);$g.Clear([Drawing.Color]::Transparent);$g.CompositingMode=[Drawing.Drawing2D.CompositingMode]::SourceCopy;$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.DrawImage($src,[Drawing.Rectangle]::new(0,0,$j.W,$j.H),[Drawing.Rectangle]::new(0,0,$src.Width,$src.Height),[Drawing.GraphicsUnit]::Pixel);$g.Dispose();$src.Dispose();if($j.Name-eq"fog_a"){for($y=0;$y-lt$j.H;$y++){for($x=[int]($j.W/2);$x-lt$j.W;$x++){$dst.SetPixel($x,$y,$dst.GetPixel($j.W-1-$x,$y))}}};$path=Join-Path $PackageRoot "approved/vfx/tr01_vfx_$($j.Name)_albedo.png";New-Item -ItemType Directory -Force ([IO.Path]::GetDirectoryName($path))|Out-Null;$dst.Save($path,[Drawing.Imaging.ImageFormat]::Png);$dst.Dispose();[pscustomobject]@{Asset="TR01-VFX-$($j.Name.ToUpper())";Canvas="$($j.W)x$($j.H)";Result="PASS"}}
